function indexWorkspaceData(){assetsByProject=new Map();for(const asset of assets){let rows=assetsByProject.get(asset.project_id)||[];rows.push(asset);assetsByProject.set(asset.project_id,rows)}for(const rows of assetsByProject.values())rows.sort((a,b)=>(a.sort_order||0)-(b.sort_order||0));emailCountByProject=new Map();for(const email of emails)emailCountByProject.set(email.project_id,(emailCountByProject.get(email.project_id)||0)+1)}
function skeleton(c){const cards=Array.from({length:c.image?4:3},()=>`<article class="workspace-skeleton ${c.image?'image-skeleton':''}"><i></i><b></b><em></em><small></small></article>`).join('');$('#bizCards').innerHTML=cards}
async function load(){if(!mode)return;let c=configs[mode],request=++listRequest,key=cacheKey(c),cached=workspaceCache.get(key),now=Date.now();if(listController)listController.abort();listController=new AbortController();if(!cached||now-cached.time>30000)skeleton(c);try{let payload;if(cached&&now-cached.time<=30000){payload=cached}else{const query=`page=1&pageSize=100&search=${encodeURIComponent($('#bizSearch').value)}&dateFrom=${encodeURIComponent($('#bizDateFrom').value)}&dateTo=${encodeURIComponent($('#bizDateTo').value)}`;const [d,a,m]=await Promise.all([api(`${c.path}?${query}`,{signal:listController.signal}),c.image?api('/api/v1/content/assets?pageSize=100',{signal:listController.signal}):Promise.resolve({items:[]}),c.after?api('/api/v1/after-sales/emails?pageSize=100',{signal:listController.signal}):Promise.resolve({items:[]})]);payload={d,a,m,time:Date.now()};workspaceCache.set(key,payload)}if(request!==listRequest)return;assets=payload.a.items||[];emails=payload.m.items||[];indexWorkspaceData();let status=$('#bizStatus').value,all=payload.d.items.filter(x=>{let after=x.content_group==='售后内容'||afterTypes.includes(afterType(x.content_type))||x.content_type?.includes('售后');return(c.after===undefined||after===c.after)&&(!status||x.status===status)&&(tab==='全部'||afterType(x.content_type)===tab||x.status===tab||insightType(x.insight_type)===tab||x.category===tab)}),size=c.image?8:6,max=Math.max(1,Math.ceil(all.length/size));if(page>max){page=max;return load()}items=all.slice((page-1)*size,page*size);const imageCount=$('#bizImageCount'),hasFilter=!!($('#bizSearch').value||$('#bizDateFrom').value||$('#bizDateTo').value||status||tab!=='全部');imageCount.hidden=!c.filters;if(c.filters&&c.image){let total=all.reduce((n,x)=>n+projectAssets(x.id).length,0);imageCount.innerHTML=hasFilter?`匹配项目：<strong>${all.length}</strong> 条 · 图片：<strong>${total}</strong> 张`:`全部图片：<strong>${total}</strong> 张`;$('#bizCompass').hidden=true;$('#bizNew').textContent='＋ 新增'+(tab==='全部'?mode:tab)}else{if(c.filters)imageCount.textContent=`已显示：${all.length} 条`;$('#bizCompass').hidden=false;if(c.timeline){$('#bizCompass').innerHTML=['全部历程','进行中','已完成'].map((t,i)=>`<div class="${i?'':'compass-total'}"><span>${t}</span><strong>${i?all.filter(x=>x.status===t).length:all.length}</strong></div>`).join('')}else if(mode==='营销方案'){$('#bizCompass').innerHTML=['方案总数','待执行','执行中','已结束','已复盘'].map((t,i)=>`<div class="${i?'':'compass-total'}"><span>${t}</span><strong>${i?all.filter(x=>x.status===t).length:all.length}</strong></div>`).join('')}else{$('#bizCompass').innerHTML=`<div class="compass-total"><span>洞察总数</span><strong>${all.length}</strong></div><div><span>已复刻</span><strong>${all.filter(x=>doneText(x.replicated)).length}</strong></div><div><span>已验证</span><strong>${all.filter(x=>doneText(x.verification)).length}</strong></div><div><span>待验证</span><strong>${all.filter(x=>!doneText(x.verification)).length}</strong></div>`}}const paint=c.timeline?milestoneCard:c.image?imageCard:contentCard;$('#bizCards').innerHTML=items.length?items.map(paint).join(''):`<div class="empty-state"><strong>${hasFilter?'暂无匹配内容':'这里还没有内容'}</strong><p>${hasFilter?'请调整筛选条件后重试。':'新建第一条记录，团队就可以开始积累与协作。'}</p>${hasFilter?'<button class="soft" data-reset-filters>重置筛选</button>':''}</div>`;$('#bizPage').textContent=`${page} / ${max}`;$('#bizPrev').disabled=page<=1;$('#bizNext').disabled=page>=max;if(c.image)bindCardDrops();paintBusinessComments()}catch(error){if(error.name==='AbortError')return;if(request!==listRequest)return;if(c.filters){$('#bizImageCount').hidden=false;$('#bizImageCount').textContent='加载失败'}$('#bizCards').innerHTML=`<div class="empty-state load-error"><strong>内容加载失败</strong><p>${esc(friendlyError(error.message))}</p><button class="soft" data-retry-load>重试</button></div>`;toast('内容加载失败，请重试')}}
const projectAssets=id=>assetsByProject.get(id)||[];
function imageFiles(event){return [...(event.dataTransfer?.files||[])].filter(file=>file.type.startsWith('image/'))}
function hasImageDrop(event){return imageFiles(event).length>0||[...(event.dataTransfer?.types||[])].includes('Files')}
function uniqueFiles(files){const seen=new Set();return files.filter(file=>{const key=`${file.name}:${file.size}:${file.lastModified}`;if(seen.has(key))return false;seen.add(key);return true})}
function wireImageDrop(node,onFiles){if(!node)return;node.ondragenter=node.ondragover=event=>{if(!hasImageDrop(event))return;event.preventDefault();node.classList.add('is-dragging')};node.ondragleave=event=>{if(!node.contains(event.relatedTarget))node.classList.remove('is-dragging')};node.ondrop=async event=>{const files=imageFiles(event);if(!files.length)return;event.preventDefault();node.classList.remove('is-dragging');await onFiles(files)}}
function bindNativeImageDrops(root=document){$$('input[type="file"][accept*="image"]',root).forEach(input=>{if(input.dataset.dragUpload)return;input.dataset.dragUpload='1';const target=input.closest('label,.asset-upload-field')||input.parentElement;wireImageDrop(target,async files=>{try{const transfer=new DataTransfer();files.forEach(file=>transfer.items.add(file));input.files=transfer.files;input.dispatchEvent(new Event('change',{bubbles:true}))}catch(error){toast('请使用“选择图片”按钮上传')}})})}
function bindCardDrops(){$$('.image-project-card[data-project-id]').forEach(card=>wireImageDrop(card,async files=>{const id=card.dataset.projectId;card.classList.add('is-uploading');try{await uploadAssets(id,files,false);await load()}catch(error){toast(friendlyError(error.message))}finally{card.classList.remove('is-uploading')}}))}
function statusTone(status){return ({'草稿':'draft','待执行':'pending','执行中':'running','制作中':'running','待审核':'pending','待修改':'pending','已结束':'ended','已通过':'completed','已发布':'completed','已复盘':'reviewed','已完成':'completed'})[status]||'neutral'}
function imageCard(x){let aa=projectAssets(x.id),cover=aa.find(a=>a.is_final)||aa[0],after=configs[mode]?.after,product=x.product||x.brand||'未关联产品',label=after?`客户生命周期：${x.usage_scene||'未设置'}`:`产品：${product}`,owner=x.owner||x.created_by||'未分配',mailCount=after?(emailCountByProject.get(x.id)||0):0,image=cover?`<button class="project-preview" data-preview-project="${x.id}" aria-label="预览 ${esc(x.name)}"><img src="/api/v1/media/${cover.media_id}/thumbnail" alt="${esc(x.name)}" loading="lazy"></button>`:`<div class="image-placeholder">${icons['品牌内容']}<span>拖拽图片到这里上传</span></div>`;return `<article class="image-project-card" data-project-id="${esc(x.id)}"><div class="project-cover"><span class="project-product">${esc(label)}</span><span class="project-owner">负责人：${esc(owner)}</span>${image}<span class="image-count">${aa.length} 张</span></div><div class="project-card-body"><div class="project-title-row"><span class="tag">${esc(afterType(x.content_type))}</span><strong class="project-inline-title">${esc(x.name)}</strong></div><p class="project-description">${esc(x.description||'暂无内容说明')}</p><div class="card-foot"><span class="hint">${after?`<b class="after-email-count">已增邮件 ${mailCount}</b> · `:''}${esc(localWhen(x.updated_at||x.created_at).slice(0,10))}</span><div class="actions"><button class="soft" data-comment="${x.id}">评价</button><button data-open="${x.id}">查看与编辑</button></div></div></div></article>`}
function contentCard(x){let title=x.name||x.title,type=mode==='竞品洞察'?insightType(x.insight_type):x.status,subject=mode==='竞品洞察'?(x.competitor||'未填写竞品'):(x.product||'未关联产品'),when=mode==='营销方案'?`${x.start_date||'未定'} — ${x.end_date||'未定'}`:localWhen(x.updated_at||x.created_at).slice(0,10),statusClass=mode==='营销方案'?` status-tag tone-${statusTone(type)}`:'';return `<article class="content-project-card"><div class="tags"><span class="tag${statusClass}">${esc(type||'未分类')}</span></div><h2>${esc(title)}</h2><div class="project-meta"><span>${esc(subject)}</span></div><div class="card-foot"><span class="hint">${esc(when)}</span><div class="actions"><button class="soft" data-comment="${x.id}">评价</button><button data-open="${x.id}">查看与编辑</button></div></div></article>`}
function milestoneCard(x){return `<article class="milestone-card"><time>${esc(x.milestone_date)}</time><div class="milestone-dot"></div><div class="milestone-body"><div class="milestone-head"><span class="milestone-category">${esc(x.category)}</span><span class="status-tag tone-${statusTone(x.status)}">${esc(x.status)}</span></div><h2>${esc(x.title)}</h2><p>${esc(x.description||'暂无过程说明')}</p><div class="milestone-meta">负责人：${esc(x.owner||x.created_by||'未分配')}　关联产品：${esc(x.product||'未关联')}</div><div class="card-foot"><span class="hint">${esc(x.outcome||'尚未填写结果 / 复盘')}</span><div class="actions"><button class="soft" data-comment="${x.id}">评价</button><button data-open="${x.id}">查看与编辑</button></div></div></div></article>`}
$('#bizCards').onclick=e=>{if(e.target.closest('[data-reset-filters]'))return resetFilters();if(e.target.closest('[data-retry-load]'))return load();let preview=e.target.closest('[data-preview-project]');if(preview){let aa=projectAssets(preview.dataset.previewProject);return lightboxGallery(aa)}let x=items.find(x=>x.id===(e.target.dataset.open||e.target.dataset.comment));if(!x)return;e.target.dataset.comment?comments(x):form(x)};$('#bizNew').onclick=()=>form(null);$('#bizUpload').onclick=()=>batch(true);

function field(k,label,v='',opts=null,wide=false,type='text'){let control=opts?`<select data-f="${k}">${opts.map(o=>`<option ${o===v?'selected':''}>${esc(o)}</option>`).join('')}</select>`:type==='textarea'?`<textarea data-f="${k}">${esc(v)}</textarea>`:`<input data-f="${k}" type="${type}" value="${esc(v)}">`;return `<label class="field ${wide?'span2':''}"><span>${label}</span>${control}</label>`}
function productField(value=''){const names=[...new Set([...productCatalog.map(row=>row.name).filter(Boolean),value].filter(Boolean))];return names.length?field('product','关联产品',value,names):field('product','关联产品',value)}
function preserved(x,keys){return x?keys.map(key=>`<input type="hidden" data-f="${key}" value="${esc(x[key]??'')}">`).join(''):''}
const section=(title,sub,body)=>`<section class="editor-section"><div class="editor-section-copy"><h3>${title}</h3><p>${sub}</p></div><div class="fields">${body}</div></section>`;
/* Compact, task-first editors.  These override the earlier field builders so the
   dialog only asks for information that is needed to publish or collaborate. */
function imageFields(x){const listed=(configs[mode].tabs||[]).filter(t=>t!=='全部'),types=listed.length?listed:(mode==='售后内容'?afterTypes:brandTypes);const chosen=afterType(x?.content_type)||(tab!=='全部'?tab:types[0]);const upload=x?'':`<div class="field span2 asset-upload-field image-drop-zone" data-new-image-drop><span>图片</span><label class="profile-upload-button"><input id="bizNewAssets" type="file" accept="image/*" multiple hidden><span>选择图片</span></label><small>或将图片拖到此处；保存项目后会沿用同一上传、原图保留和去重逻辑。</small></div>`;const fields=mode==='售后内容'?field('name','内容名称',x?.name)+field('content_type','内容类型',chosen,types)+field('usage_scene','客户生命周期',x?.usage_scene||lifecycle[0],lifecycle)+productField(x?.product)+field('owner','负责人',x?.owner||serverUser.username)+field('description','内容说明',x?.description,null,true,'textarea')+upload:field('name','项目名称',x?.name)+field('content_type','图片类型',chosen,types)+field('brand','品牌',x?.brand)+productField(x?.product)+field('owner','负责人',x?.owner||serverUser.username)+field('description','内容说明',x?.description,null,true,'textarea')+upload;const keep=mode==='售后内容'?preserved(x,['brand','due_date','page_url','selling_point_order','channel','status']):preserved(x,['due_date','channel','page_url','status']);return `<section class="editor-section"><div class="fields">${fields}</div></section>`+keep}
const dateRangeFields=(startKey,startLabel,startValue,endKey,endLabel,endValue)=>`<div class="date-range-fields span2"><span>日期范围</span>${field(startKey,startLabel,startValue,null,false,'date')}${field(endKey,endLabel,endValue,null,false,'date')}</div>`;
function marketingFields(x){return `<section class="editor-section"><div class="fields">${field('name','方案名称',x?.name)+field('goal','方案目标',x?.goal)+productField(x?.product)+field('status','状态',x?.status||'草稿',configs['营销方案'].status)+field('owner','负责人',x?.owner||serverUser.username)+dateRangeFields('start_date','开始日期',x?.start_date,'end_date','结束日期',x?.end_date)+field('execution_plan','执行计划',x?.execution_plan,null,true,'textarea')}</div></section>`+preserved(x,['benefit','offer','content_list','target_metrics','review_notes','audience','channels'])}
function milestoneFields(x){const categories=configs['品牌历程'].tabs.slice(1);return `<section class="editor-section"><div class="fields">${dateRangeFields('milestone_date','开始日期',x?.milestone_date||new Date().toISOString().slice(0,10),'end_date','结束日期（可选）',x?.end_date)+field('category','历程分类',x?.category||categories[0],categories)+field('status','当前状态',x?.status||'进行中',configs['品牌历程'].status)+field('title','历程标题',x?.title)+field('owner','负责人',x?.owner||serverUser.username)+productField(x?.product)+field('related_item','关联内容 / 方案',x?.related_item,null,true)+field('description','过程说明',x?.description,null,true,'textarea')+field('outcome','结果 / 复盘',x?.outcome,null,true,'textarea')}</div></section>`}
function competitorFields(x){const types=configs['竞品洞察'].tabs.slice(1);return `<section class="editor-section"><div class="fields">${field('competitor','竞品名称',x?.competitor)+field('insight_type','研究类型',insightType(x?.insight_type)||types[0],types)+field('title','洞察标题',x?.title)+field('source_url','来源链接',x?.source_url,null,false,'url')+field('research','结论',x?.research,null,true,'textarea')+`<div class="field span2 asset-upload-field image-drop-zone" data-competitor-drop><span>截图</span><label class="profile-upload-button"><input id="competitorMedia" type="file" accept="image/*" hidden><span>选择图片</span></label><small>也可拖拽一张图片到此处。</small>${x?.media_id?`<img class="editor-media-preview" src="/api/v1/media/${x.media_id}/thumbnail" alt="">`:''}</div>`}</div></section>`+preserved(x,['product','owner','takeaway','replicated','verification'])}
function showBizError(message){let box=$('#bizError');if(!box){box=document.createElement('p');box.id='bizError';box.className='form-error';$('#bizFields').prepend(box)}box.textContent=message;box.hidden=false;$('#bizFields').scrollTop=0;toast(message)}
function clearBizError(){$('#bizError')?.remove();$('#bizSave').disabled=false}
function fieldLabel(key){const el=$(`[data-f="${key}"]`,$('#bizFields'));return el?.closest('label')?.querySelector('span')?.textContent||key}
function friendlyError(message){const match=String(message||'').match(/^缺少字段：(.+)$/);return match?`请填写${fieldLabel(match[1])}`:(message||'保存失败')}
function bindEditorDrops(){const newZone=$('[data-new-image-drop]'),competitorZone=$('[data-competitor-drop]');wireImageDrop(newZone,async files=>{stagedNewAssets=uniqueFiles([...stagedNewAssets,...files]);newZone.querySelector('small').textContent=`已暂存 ${stagedNewAssets.length} 张图片，保存项目后上传。`});wireImageDrop(competitorZone,async files=>{stagedCompetitorAsset=files[0];competitorZone.querySelector('small').textContent=`已选择：${stagedCompetitorAsset.name}`})}
function form(x){editing=x;stagedNewAssets=[];stagedCompetitorAsset=null;clearBizError();$('#bizDialogTitle').textContent=(x?'编辑':'新建')+(configs[mode].image?(x?.content_type||mode):mode);$('#bizDelete').hidden=!x;$('#bizEmails').hidden=!(mode==='售后内容'&&x);$('#bizEmails').onclick=()=>afterSalesEmails(x);$('#bizFields').innerHTML=(configs[mode].image?imageFields(x):mode==='营销方案'?marketingFields(x):mode==='品牌历程'?milestoneFields(x):competitorFields(x))+(x&&configs[mode].image?track(x.id):'');dialog.showModal();requestAnimationFrame(()=>{const fields=$('#bizFields');if(fields)fields.scrollTop=0;dialog.querySelector('[data-f]')?.focus({preventScroll:true})});if(x&&configs[mode].image)bindTrack(x.id);bindEditorDrops()}
/* Dynamic records have two storage models. Resolve the referenced record first,
   then open its native module instead of re-rendering the legacy homepage. */
const notificationResourceRoutes={marketing_plans:'营销方案',competitor_insights:'竞品洞察',brand_milestones:'品牌历程',lifecycle_plans:'售后内容'};
const notificationResourcePaths={brand_content_projects:'/api/v1/content/projects?page=1&pageSize=100',marketing_plans:'/api/v1/marketing/plans?page=1&pageSize=100',competitor_insights:'/api/v1/competitors?page=1&pageSize=100',brand_milestones:'/api/v1/brand/milestones?page=1&pageSize=100'};
async function openBusinessNotification(record,route){await open(route);form(record)}
window.EkkoOpenNotification=async function(event){const id=String(event?.entryId||''),kind=String(event?.kind||'');if(!id)throw Error('动态内容无效');const legacyKinds={创意钩子:0,开头创意:0,产品出场:1,完整脚本:2,scripts:2,product_entries:1,creative_hooks:0};if(Object.prototype.hasOwnProperty.call(legacyKinds,kind)){const state=await api('/api/state');entries=state.entries||[];version=state.version;const record=entries.find(item=>String(item.id)===id);if(!record)throw Error('该内容已归档');openCreative();selectCreative(legacyKinds[kind]);detail(record);return}if(kind==='brand_content_projects'){const data=await api(notificationResourcePaths.brand_content_projects),record=(data.items||[]).find(item=>String(item.id)===id);if(!record)throw Error('该内容已归档');return openBusinessNotification(record,record.content_group==='售后内容'?'售后内容':'品牌内容')}if(notificationResourceRoutes[kind]){const path=notificationResourcePaths[kind]||notificationResourcePaths.brand_content_projects,data=await api(path),record=(data.items||[]).find(item=>String(item.id)===id);if(!record)throw Error('该内容已归档');return openBusinessNotification(record,notificationResourceRoutes[kind])}if(kind==='团队评价'){const state=await api('/api/state');entries=state.entries||[];version=state.version;const legacyRecord=entries.find(item=>String(item.id)===id);if(legacyRecord){openCreative();detail(legacyRecord);return}for(const [table,path] of Object.entries(notificationResourcePaths)){const data=await api(path),record=(data.items||[]).find(item=>String(item.id)===id);if(!record)continue;const route=table==='brand_content_projects'?(record.content_group==='售后内容'?'售后内容':'品牌内容'):notificationResourceRoutes[table];return openBusinessNotification(record,route)}}throw Error('该动态关联内容已归档或暂不支持定位')};
$('#bizClose').onclick=()=>{clearBizError();dialog.close()};
function track(id){let aa=projectAssets(id);return `<section class="editor-section image-track-section"><div class="editor-section-copy"><h3>图片</h3><div class="asset-upload-actions"><label class="profile-upload-button"><input id="bizAssetUpload" type="file" accept="image/*" multiple hidden><span>批量上传</span></label><label class="profile-upload-button"><input id="bizAssetAdd" type="file" accept="image/*" hidden><span>＋ 增加图片</span></label></div></div><div class="asset-rail image-drop-zone" id="bizAssets">${aa.length?aa.map((a,i)=>assetCard(a,i,aa.length)).join(''):'<div class="empty-state"><strong>还没有图片</strong><p>拖拽图片到这里，或使用上方按钮上传。</p></div>'}</div></section>`}
function assetCard(a,i,n){return `<article class="asset-card" draggable="true" data-asset="${a.id}"><button class="asset-zoom" data-zoom="${a.media_id}"><img src="/api/v1/media/${a.media_id}/thumbnail" alt="${esc(a.role||'图片')}"></button><div class="asset-card-copy"><strong>${esc(a.role||'未命名图片')}</strong><span class="tag">V${a.version_no||1}${a.is_final?' · 最终稿':''}</span></div><div class="asset-card-actions"><button class="soft" data-move="${a.id}" data-dir="-1" ${i?'':'disabled'}>左移</button><button class="soft" data-move="${a.id}" data-dir="1" ${i===n-1?'disabled':''}>右移</button><label class="soft">更换<input type="file" accept="image/*" data-replace="${a.id}" hidden></label><a class="soft" href="/api/v1/media/${a.media_id}/original" target="_blank">原图</a><button class="red" data-remove="${a.id}">删除</button></div></article>`}
async function uploadMedia(file){let fd=new FormData();fd.append('file',file);return api('/api/v1/media/upload',{method:'POST',body:fd})}
async function uploadAssets(id,files,refreshEditor=true,onProgress=null){let aa=projectAssets(id),uploaded=0;for(let [i,file]of files.entries()){onProgress?.(i,files.length,file.name);let m=await uploadMedia(file);if(aa.some(a=>a.sha256&&a.sha256===m.sha256)){toast(`${file.name} 重复，已跳过`);continue}await api('/api/v1/content/assets',{method:'POST',body:JSON.stringify({project_id:id,media_id:m.id,role:file.name,sort_order:aa.length+i,review_status:'待审核',version_no:1,width:m.width,height:m.height,byte_size:m.byte_size,mime:m.mime,sha256:m.sha256,uploader:serverUser.username,uploaded_at:m.created_at})});uploaded++}invalidateWorkspaceCache();if(refreshEditor)await refresh(id);else assets=(await api('/api/v1/content/assets?pageSize=100')).items;toast(uploaded?`图片上传完成：${uploaded} 张`:'没有可上传的新图片')}
async function refresh(id){invalidateWorkspaceCache();assets=(await api('/api/v1/content/assets?pageSize=100')).items;indexWorkspaceData();let tmp=document.createElement('div');tmp.innerHTML=track(id);$('.image-track-section').replaceWith($('.image-track-section',tmp));bindTrack(id);load()}
function bindTrack(id){let rail=$('#bizAssets');$('#bizAssetUpload').onchange=e=>uploadAssets(id,[...e.target.files]);$('#bizAssetAdd').onchange=e=>uploadAssets(id,[...e.target.files]);rail.onclick=async e=>{let del=e.target.dataset.remove,mv=e.target.dataset.move,zoom=e.target.closest('[data-zoom]')?.dataset.zoom;if(zoom)return lightbox(zoom);if(del)return ask('删除图片记录？','项目记录会删除，但原图仍永久保留。',async()=>{await api(`/api/v1/content/assets/${del}`,{method:'DELETE'});refresh(id)});if(mv){let aa=projectAssets(id),i=aa.findIndex(a=>a.id===mv),j=i+(+e.target.dataset.dir);if(j<0||j>=aa.length)return;await Promise.all([api(`/api/v1/content/assets/${aa[i].id}`,{method:'PUT',body:JSON.stringify({sort_order:aa[j].sort_order})}),api(`/api/v1/content/assets/${aa[j].id}`,{method:'PUT',body:JSON.stringify({sort_order:aa[i].sort_order})})]);refresh(id)}};rail.onchange=async e=>{let id2=e.target.dataset.replace,file=e.target.files?.[0];if(!id2||!file)return;let m=await uploadMedia(file),a=projectAssets(id).find(x=>x.id===id2);await api(`/api/v1/content/assets/${id2}`,{method:'PUT',body:JSON.stringify({media_id:m.id,role:file.name,version_no:+(a.version_no||1)+1,width:m.width,height:m.height,byte_size:m.byte_size,mime:m.mime,sha256:m.sha256})});refresh(id);toast('图片已更换，旧原图仍保留')};let drag;rail.ondragstart=e=>drag=e.target.closest('[data-asset]')?.dataset.asset;rail.ondragover=e=>e.preventDefault();rail.ondrop=async e=>{const files=imageFiles(e);e.preventDefault();if(files.length){await uploadAssets(id,files);return}let target=e.target.closest('[data-asset]')?.dataset.asset;if(!drag||!target||drag===target)return;let aa=projectAssets(id),from=aa.findIndex(a=>a.id===drag),to=aa.findIndex(a=>a.id===target),[m]=aa.splice(from,1);aa.splice(to,0,m);await Promise.all(aa.map((a,i)=>api(`/api/v1/content/assets/${a.id}`,{method:'PUT',body:JSON.stringify({sort_order:i})})));refresh(id)}}
async function afterSalesEmails(project){dialog.close();let rows=[],editingEmail=null,d=document.createElement('dialog');d.className='after-email-dialog';const backToProject=()=>{d.close();d.remove();form(project)};const reload=async()=>{rows=(await api(`/api/v1/after-sales/emails?pageSize=100&project_id=${encodeURIComponent(project.id)}`)).items||[]};const draw=()=>{if(editingEmail!==null){const row=editingEmail||{};d.innerHTML=`<div class="modal after-email-editor"><div class="modal-head"><h2>${row.id?'编辑邮件':'新增邮件'} · ${esc(project.name)}</h2><button class="soft" data-back>返回邮件列表</button></div><div class="fields"><label class="field"><span>标题</span><input data-email="title" value="${esc(row.title||'')}"></label><label class="field"><span>预览文本</span><input data-email="preview_text" value="${esc(row.preview_text||'')}"></label><label class="field span2"><span>正文</span><textarea data-email="body" placeholder="写入邮件正文，可使用换行。">${esc(row.body||'')}</textarea></label></div><div class="modal-foot"><button class="soft" data-back>取消</button><button data-save-email>保存邮件</button></div></div>`;return}d.innerHTML=`<div class="modal after-email-list"><div class="modal-head"><div><h2>邮件内容 · ${esc(project.name)}</h2><p class="hint">新增、复制、编辑或删除此售后方案关联的邮件。</p></div><div class="actions"><button class="soft" data-return>返回方案编辑</button><button class="soft" data-close>关闭</button></div></div><div class="after-email-actions"><button data-new-email>＋ 新增邮件</button></div><div class="email-list">${rows.length?rows.map(row=>`<article class="email-card"><h3>${esc(row.title)}</h3><p class="email-preview">${esc(row.preview_text||'暂无预览文本')}</p><div class="email-body">${esc(row.body||'暂无正文')}</div><div class="actions"><button class="soft" data-copy-email="${row.id}">复制</button><button class="soft" data-edit-email="${row.id}">编辑</button><button class="red" data-delete-email="${row.id}">删除</button></div></article>`).join(''):'<div class="empty-state"><strong>还没有邮件</strong><p>点击“新增邮件”建立第一封售后邮件。</p></div>'}</div></div>`};await reload();draw();document.body.append(d);d.showModal();d.onclick=async event=>{if(event.target.closest('[data-return]'))return backToProject();if(event.target.closest('[data-close]')){d.close();d.remove();return}if(event.target.closest('[data-back]')){editingEmail=null;draw();return}if(event.target.closest('[data-new-email]')){editingEmail={};draw();return}const id=event.target.closest('[data-edit-email]')?.dataset.editEmail||event.target.closest('[data-copy-email]')?.dataset.copyEmail;if(id){const source=rows.find(row=>row.id===id);if(event.target.closest('[data-copy-email]')){editingEmail={...source,id:null,title:`${source.title}（副本）`}}else editingEmail=source;draw();return}const del=event.target.closest('[data-delete-email]')?.dataset.deleteEmail;if(del)return ask('删除这封邮件？','删除后可由管理员恢复。',async()=>{await api(`/api/v1/after-sales/emails/${del}`,{method:'DELETE'});await reload();draw()});if(event.target.closest('[data-save-email]')){let body={project_id:project.id};$$('[data-email]',d).forEach(node=>body[node.dataset.email]=node.value.trim());if(!body.title)return toast('请填写邮件标题');if(editingEmail?.id)body.version=editingEmail.version;await api(editingEmail?.id?`/api/v1/after-sales/emails/${editingEmail.id}`:'/api/v1/after-sales/emails',{method:editingEmail?.id?'PUT':'POST',body:JSON.stringify(body)});await reload();editingEmail=null;draw();load();toast('邮件已保存')}}}
function lightbox(id){let d=document.createElement('dialog');d.className='image-lightbox';d.innerHTML=`<button class="soft lightbox-close">关闭</button><a class="soft lightbox-original" href="/api/v1/media/${id}/original" target="_blank">下载原图</a><img src="/api/v1/media/${id}/preview" alt="图片预览">`;document.body.append(d);d.showModal();$('.lightbox-close',d).onclick=()=>{d.close();d.remove()}}
async function lightboxGallery(aa){aa=aa.filter(a=>a.media_id);if(!aa.length)return toast('这个项目还没有图片');const ready=await Promise.all(aa.map(async a=>{try{const res=await fetch(`/api/v1/media/${a.media_id}/preview`);const type=res.headers.get('content-type')||'';return res.ok&&!type.includes('svg')?a:null}catch(e){return null}}));aa=ready.filter(Boolean);if(!aa.length)return toast('这些图片已经不在了');let i=0,token=0,d=document.createElement('dialog');d.className='image-lightbox image-gallery';const draw=()=>{if(!aa.length){d.close();d.remove();return toast('这些图片已经不在了')}if(i>=aa.length)i=aa.length-1;if(i<0)i=0;let a=aa[i],mine=++token;d.innerHTML=`<button class="soft lightbox-close">关闭</button><a class="soft lightbox-original" href="/api/v1/media/${a.media_id}/original" target="_blank">下载原图</a><div class="lightbox-stage"><button class="soft lightbox-prev" ${i?'':'disabled'}>上一张</button><img src="/api/v1/media/${a.media_id}/preview" alt="${esc(a.role||'图片预览')}"><button class="soft lightbox-next" ${i===aa.length-1?'disabled':''}>下一张</button></div><span class="lightbox-count">${i+1} / ${aa.length}</span>`;const img=$('img',d),drop=()=>{if(mine!==token)return;aa.splice(i,1);draw()};img.onerror=drop;img.onload=()=>{if(mine===token&&!img.naturalWidth)drop()};$('.lightbox-close',d).onclick=()=>{d.close();d.remove()};$('.lightbox-prev',d).onclick=()=>{i--;draw()};$('.lightbox-next',d).onclick=()=>{i++;draw()}};draw();document.body.append(d);d.showModal()}
async function batch(){let all=(await api('/api/v1/content/projects?pageSize=100')).items.filter(x=>(x.content_group==='售后内容')===(mode==='售后内容'));if(!all.length){toast('请先新建项目');return form(null)}let chosen=[],d=document.createElement('dialog');d.className='upload-dialog';d.innerHTML=`<div class="modal"><div class="modal-head"><h2>上传图片</h2><button class="soft" data-close>关闭</button></div><div class="fields"><label class="field"><span>上传到项目</span><select id="batchProject">${all.map(x=>`<option value="${x.id}">${esc(x.name)}</option>`).join('')}</select></label><label class="field"><span>选择图片</span><input id="batchFiles" type="file" accept="image/*" multiple></label><div class="field span2 image-drop-zone" id="batchDrop"><strong>拖拽图片到这里上传</strong><small>支持多选；将保留原图，并生成 WebP 页面预览与缩略图。</small></div></div><div class="modal-foot"><button id="batchGo">开始上传</button></div></div>`;document.body.append(d);d.showModal();const summary=files=>{$('#batchDrop',d).querySelector('small').textContent=files.length?`已选择 ${files.length} 张图片，等待上传。`:'支持多选；将保留原图，并生成 WebP 页面预览与缩略图。'};$('#batchFiles',d).onchange=e=>{chosen=[...e.target.files];summary(chosen)};wireImageDrop($('#batchDrop',d),async files=>{chosen=uniqueFiles([...chosen,...files]);summary(chosen)});$('[data-close]',d).onclick=()=>{d.close();d.remove()};$('#batchGo',d).onclick=async()=>{if(!chosen.length)return toast('请先选择或拖入图片');const button=$('#batchGo',d);setBusy(button,true,`上传中 0 / ${chosen.length}`);try{await uploadAssets($('#batchProject',d).value,chosen,true,(index,total)=>button.textContent=`◌ 上传中 ${index+1} / ${total}`);d.close();d.remove();await load()}catch(error){toast(friendlyError(error.message));setBusy(button,false)}}}
$('#bizSave').onclick=async()=>{const button=$('#bizSave');if(button.disabled)return;setBusy(button,true,'保存中…');let c=configs[mode],body={};$$('[data-f]',$('#bizFields')).forEach(n=>body[n.dataset.f]=n.value.trim());if(c.image)body.content_group=c.after?'售后内容':groupOf(body.content_type);if(editing)body.version=editing.version;const required=c.image?['name']:mode==='营销方案'?['name']:mode==='品牌历程'?['milestone_date','category','title']:['competitor','title','insight_type'];const missing=required.filter(key=>!body[key]);if(missing.length){showBizError('请填写'+missing.map(fieldLabel).join('、'));setBusy(button,false);$(`[data-f="${missing[0]}"]`,$('#bizFields'))?.focus();return}const start=body.start_date||body.milestone_date,end=body.end_date;if(end&&start&&end<start){showBizError('结束日期不能早于开始日期');setBusy(button,false);return}try{let file=stagedCompetitorAsset||$('#competitorMedia')?.files?.[0];if(file)body.media_id=(await uploadMedia(file)).id;const saved=await api(editing?`${c.path}/${editing.id}`:c.path,{method:editing?'PUT':'POST',body:JSON.stringify(body)});const newFiles=uniqueFiles([...($('#bizNewAssets')?.files||[]),...stagedNewAssets]);if(c.image&&newFiles.length)await uploadAssets(saved.id,newFiles,false);invalidateWorkspaceCache();clearBizError();dialog.close();await load();home();toast('已保存')}catch(e){showBizError(friendlyError(e.message))}finally{setBusy(button,false)}};
$('#bizDelete').onclick=()=>editing&&ask('删除这条内容？','删除后会移入“删除与恢复”，管理员可恢复。',async()=>{await api(`${configs[mode].path}/${editing.id}`,{method:'DELETE'});invalidateWorkspaceCache();dialog.close();await load();toast('已移入删除与恢复')});
function entity(){return configs[mode].image?'brand_content':mode==='营销方案'?'marketing_plan':mode==='品牌历程'?'brand_milestone':'competitor_insight'}
const commentView={mode:'new',page:1};
function commentActor(row){return row.actor||row.name||row.username||''}
function commentCanDelete(row){return commentActor(row)===serverUser.username||row.username===serverUser.username||serverUser.role==='admin'}
function commentLines(rows){return rows.map(row=>`<div class="comment-line"><small>${esc(commentActor(row))} · ${esc(localWhen(row.time).slice(0,19))}</small><p>${esc(row.content)}</p>${(row.replies||[]).map(reply=>`<div class="comment-line comment-reply"><small>${esc(reply.actor)} · 回复</small><p>${esc(reply.content)}</p></div>`).join('')}<div class="actions"><button type="button" class="quiet-action" data-like="${row.id}">${row.liked?'取消点赞':'点赞'} ${row.likes||0}</button><button type="button" class="quiet-action" data-reply="${row.id}">回复</button>${commentCanDelete(row)?`<button type="button" class="quiet-action" data-del="${row.id}">删除</button>`:''}</div></div>`).join('')||'<p class="hint">写下第一条评价，帮助团队完善内容。</p>'}
function commentShell(hint, rows){const list=[...rows].sort((a,b)=>commentView.mode==='likes'?((b.likes||0)-(a.likes||0)||String(b.time||'').localeCompare(String(a.time||''))):String(b.time||'').localeCompare(String(a.time||'')));const size=3,max=Math.max(1,Math.ceil(list.length/size)||1);commentView.page=Math.min(Math.max(1,commentView.page),max);const slice=list.slice((commentView.page-1)*size,commentView.page*size);const sort=(mode,label)=>`<button type="button" class="comment-sort-btn${commentView.mode===mode?' active':''}" data-sort="${mode}">${label}</button>`;return `<div class="modal"><div class="modal-head comment-head"><div><h2>团队评价</h2><p class="hint">${hint}</p></div><div class="comment-sort">${sort('new','最新')}${sort('likes','点赞最多')}<span class="hint">${list.length} 条</span><button type="button" class="soft" data-close>关闭</button></div></div><div class="comment-list">${commentLines(slice)}</div><div class="pagination"><button type="button" class="soft" data-comment-prev ${commentView.page<=1?'disabled':''}>上一页</button><span>${commentView.page} / ${max}</span><button type="button" class="soft" data-comment-next ${commentView.page>=max?'disabled':''}>下一页</button></div><form class="comment-compose" data-comment-form><label class="field"><span>评价内容</span><textarea required maxlength="2000" placeholder="写下具体、可执行的团队评价…"></textarea></label><button>发布评价</button></form></div>`}
function latestCardComment(rows){const latest=[...(rows||[])].sort((a,b)=>String(b.time||'').localeCompare(String(a.time||'')))[0];if(!latest)return '';return `<div class="card-comment-preview latest-card-comment"><p>评价：${esc(latest.content)}</p><small>👍 ${latest.likes||0} · ${esc(commentActor(latest)||'匿名成员')} · ${esc(localWhen(latest.time).slice(0,10))}</small></div>`}
async function paintBusinessComments(){const root=$('#bizCards');if(!root)return;root.querySelectorAll('.card-comment-preview').forEach(node=>node.remove());if(!configs[mode]?.image||!items.length)return;try{const previews=await api(`/api/v1/comment-previews?ids=${encodeURIComponent(items.map(item=>item.id).join(','))}`);items.forEach(item=>{const markup=latestCardComment(previews[item.id]);if(!markup)return;const card=root.querySelector(`[data-project-id="${CSS.escape(item.id)}"]`);card?.querySelector('.project-description')?.insertAdjacentHTML('afterend',markup)})}catch(error){console.warn('评价摘要读取失败',error)}}
document.addEventListener('ekko:comments',()=>paintBusinessComments());
async function comments(x){commentView.mode='new';commentView.page=1;let rows=await api(`/api/v1/comments/${entity()}/${x.id}`),d=document.createElement('dialog');d.className='business-comments-dialog';const draw=()=>{d.innerHTML=commentShell(esc(x.name||x.title),rows);$('[data-close]',d).onclick=()=>d.close()};draw();document.body.append(d);d.showModal();const live=async()=>{if(!d.open||document.activeElement?.closest('.comment-compose'))return;rows=await api(`/api/v1/comments/${entity()}/${x.id}`);draw()};document.addEventListener('ekko:comments',live);d.addEventListener('close',()=>{document.removeEventListener('ekko:comments',live);d.remove();paintBusinessComments()},{once:true});d.onclick=async e=>{const target=e.target instanceof Element?e.target:null,sort=target?.closest('[data-sort]'),prev=target?.closest('[data-comment-prev]'),next=target?.closest('[data-comment-next]'),action=target?.closest('[data-like],[data-reply],[data-del]');if(sort){commentView.mode=sort.dataset.sort;commentView.page=1;return draw()}if(prev){commentView.page--;return draw()}if(next){commentView.page++;return draw()}if(!action)return;const {like,reply,del}=action.dataset;if(like){await api(`/api/v1/comments/${like}/like`,{method:'POST'});rows=await api(`/api/v1/comments/${entity()}/${x.id}`);return draw()}if(reply){let content=await textPrompt('回复评价','写下回复内容');if(content){await api(`/api/v1/comments/${reply}/replies`,{method:'POST',body:JSON.stringify({content})});rows=await api(`/api/v1/comments/${entity()}/${x.id}`);draw()}return}if(del)return ask('请确认','是否删除这条评价？',async()=>{await api(`/api/v1/comments/${del}`,{method:'DELETE'});rows=await api(`/api/v1/comments/${entity()}/${x.id}`);draw()})};d.addEventListener('change',e=>{const target=e.target instanceof Element?e.target:null;if(!target?.matches('[data-comment-sort]'))return;commentView.mode=target.value;commentView.page=1;draw()});d.addEventListener('submit',async e=>{const target=e.target instanceof Element?e.target:null,form=target?.closest('[data-comment-form]'),input=form?.querySelector('textarea');if(!form||!input)return;e.preventDefault();let value=input.value.trim();if(!value)return;await api('/api/v1/comments',{method:'POST',body:JSON.stringify({entityType:entity(),entityId:x.id,content:value})});rows=await api(`/api/v1/comments/${entity()}/${x.id}`);commentView.page=1;draw();document.dispatchEvent(new Event('ekko:comments'));toast('评价已发布');paintBusinessComments()});}

function textPrompt(title,placeholder){return new Promise(resolve=>{let d=document.createElement('dialog');d.className='workshop-dialog';d.innerHTML=`<div class="modal-head"><h2>${esc(title)}</h2><button class="soft" type="button">关闭</button></div><form class="comment-compose reply-compose"><input required autofocus placeholder="${esc(placeholder)}"><button>发布回复</button></form>`;document.body.append(d);$('button[type="button"]',d).onclick=()=>{d.close();d.remove();resolve('')};$('form',d).onsubmit=e=>{e.preventDefault();let value=$('input',d).value.trim();d.close();d.remove();resolve(value)};d.showModal()})}
