if(!$('#businessHomeSection')){let h=document.createElement('div');h.id='businessHomeSection';h.className='home-section';h.innerHTML='<div class="home-section-head"><div><h2>品牌内容与执行进度</h2><p class="hint">团队内容资产与执行状态。</p></div></div><div class="overview-grid" id="businessOverview"></div>';const anchor=$('#latestConversion')||$('#homeRecent')?.closest('.home-section')||$('#homeView .home-footer');anchor?.before(h)}
