function newProduct(){let d=document.createElement('dialog');d.className='product-editor-dialog';d.innerHTML=`<form class="modal"><div class="modal-head"><div><h2>新建产品</h2><p class="hint">保存后可在品牌内容、营销方案、售后内容和品牌历程中关联。</p></div><button type="button" class="soft" data-close>关闭</button></div><div class="fields"><label class="field"><span>产品名称</span><input name="name" required autofocus></label><label class="field"><span>所属品牌</span><input name="brand" value="Sana"></label><label class="field"><span>负责人</span><input name="owner" value="${esc(serverUser.username)}"></label><label class="field"><span>状态</span><select name="status"><option>开发中</option><option>在售</option><option>停售</option></select></label><label class="field span2"><span>产品说明</span><textarea name="description" placeholder="记录定位、核心卖点或当前阶段。"></textarea></label></div><div class="modal-foot"><button type="button" class="soft" data-close>取消</button><button>保存产品</button></div></form>`;document.body.append(d);d.showModal();$$('[data-close]',d).forEach(button=>button.onclick=()=>{d.close();d.remove()});$('form',d).onsubmit=async event=>{event.preventDefault();const form=event.currentTarget,body=Object.fromEntries(new FormData(form).entries());try{await api('/api/v1/products',{method:'POST',body:JSON.stringify(body)});await syncProducts();d.close();d.remove();toast('产品已新建，可在各模块关联')}catch(error){toast(friendlyError(error.message))}}}
