/* 类型管理：业务模块沿用品牌创意的同一张弹窗，数据只跟当前页面走。 */
const typeGroupName=()=>({'品牌内容':'brand_content','售后内容':'after_sales','营销方案':'marketing_plan','竞品洞察':'competitor_insight'})[mode];
const savedGroup=$('#typeGroup')?.innerHTML||'',savedOrigin=$('#newTypeOrigin')?.innerHTML||'';
