/* 更新日志：按日期分组、分页浏览。筛选属于业务列表，不属于发布记录。 */
function openChangelog(){
 const releases=[
  {date:'2026-11-16',title:'模块首行与卡片信息优化',body:'品牌创意、品牌内容、营销方案、售后内容、广告复盘和竞品洞察统一为“标语—模块名—说明—工具栏”的桌面单行布局，并整体收紧导航下方留白。图片卡片的最新评价元信息加大为黑色斜体；分类按钮增强默认底色和字号，图片数量数字使用醒目的红色加粗显示。',author:'ekko'},
  {date:'2026-11-16',title:'评价、类型和页面位置',body:'团队评价的排序改到标题右侧，直接点“最新”或“点赞最多”，每页显示 3 条。卡片上保留两条评价，类型用绿色标出，后面写评价内容和昵称。类型统计收成一行。更新日志按日期筛选，一页 5 条。永久删除的确认框不再把页面挤偏。首页最近脚本把标题和编号完整显示出来。',author:'ekko'},
  {date:'2026-11-16',title:'工具栏、评价和删除提示',body:'各模块工具栏按搜索、筛选和按钮收紧，不再留出空白。卡片日期上方最多显示两条评价，更多评价在弹窗里按最新或点赞最多查看。永久删除成功的提示显示在当前弹窗上面。',author:'ekko'},
  {date:'2026-11-16',title:'类型卡片、记录筛选与加载',body:'品牌内容、营销方案、售后内容、竞品洞察和品牌创意的类型管理改成同一张卡片：点标签修改，右侧新增。删除类型只去掉分类，不删除已经写好的内容。操作记录可以按姓名、内容和日期筛选，一页 10 条。永久删除不再报错，打开确认框时页面和卡片不再跟着偏移。首页“品牌内容与执行进度”先显示再补上数字。各模块搜索框收成提示文字的宽度。',author:'ekko'},
  {date:'2026-11-16',title:'布局与管理修正',body:'整站缩放到 95%。操作记录改为一页 10 条，用上一页和下一页查看。删除与恢复增加永久删除。导航去掉账号管理和修改密码：修改密码在个人资料，账号管理在管理端。各模块类型管理沿用品牌创意的弹窗，并且只显示当前页面的类型。',author:'ekko'},
  {date:'2026-11-14',title:'页面结构与编辑优化',body:'移除旧导航与加载遮罩；统一模块筛选位置、评价弹窗、原生日历和图片创建上传。',author:'ekko'},
  {date:'2026-11-13',title:'稳定性与组件统一',body:'修复登录旧界面闪现、图片预览残留；统一统计卡片、日期区间和评价实时更新。',author:'ekko'},
  {date:'2026-11-13',title:'评价与预览更新',body:'统一评价与回复、图片画廊和模块类型维护。',author:'ekko'},
  {date:'2026-11-12',title:'上线架构更新',body:'接入 PostgreSQL、Redis、MinIO 与权限控制。',author:'ekko'}
 ];
 let page=1;
 const d=document.createElement('dialog');
 document.body.append(d);
 const draw=()=>{
  const rows=releases;
  const size=5,max=Math.max(1,Math.ceil(rows.length/size));
  page=Math.min(Math.max(1,page),max);
  const slice=rows.slice((page-1)*size,page*size),groups=[];
  slice.forEach(item=>{let group=groups.find(row=>row.date===item.date);if(!group){group={date:item.date,items:[],total:rows.filter(row=>row.date===item.date).length};groups.push(group)}group.items.push(item)});
  d.innerHTML=`<div class="modal changelog-modal"><div class="modal-head"><h2>更新日志</h2><button class="soft" data-close>关闭</button></div><div class="release-list">${groups.map(group=>`<section class="release-day"><h3>● ${group.date}<small>（共 ${group.total} 项更新）</small></h3>${group.items.map(item=>`<article><div><h4>${esc(item.title)}</h4><p>${esc(item.body)}</p></div><small>发布人：${esc(item.author)}</small></article>`).join('')}</section>`).join('')}</div><div class="pagination"><button type="button" class="soft" data-log-prev ${page<=1?'disabled':''}>上一页</button><span>${page} / ${max}</span><button type="button" class="soft" data-log-next ${page>=max?'disabled':''}>下一页</button></div></div>`;
 };
 d.addEventListener('click',event=>{
  if(event.target.closest('[data-close]'))return d.close();
  if(event.target.closest('[data-log-prev]')){page--;return draw()}
  if(event.target.closest('[data-log-next]')){page++;return draw()}
 });
 draw();
 d.showModal();
}
if(serverUser?.role==='admin'&&$('#workshopAdmin .admin-sections')&&!$('#adminChangelog')){const b=document.createElement('button');b.id='adminChangelog';b.className='soft';b.textContent='更新日志';$('#workshopAdmin .admin-sections').append(b);b.onclick=openChangelog}

/* Unified date-range popover; quick choices live inside the panel. */
const datePicker=document.createElement('dialog');datePicker.className='date-range-picker';datePicker.innerHTML=`<form method="dialog"><h2>日期筛选</h2><div class="date-presets"><button type="button" data-range="all">全部时间</button><button type="button" data-range="week">最近 7 天</button><button type="button" data-range="month30">最近 30 天</button><button type="button" data-range="month">本月</button></div><div class="date-range-fields"><label>开始日期<input class="native-date" name="from" type="date"></label><label>结束日期<input class="native-date" name="to" type="date"></label></div><div class="date-range-actions"><button type="button" class="soft" data-date-cancel>取消</button><button type="submit">应用日期筛选</button></div></form>`;document.body.append(datePicker);const dateForm=$('form',datePicker);let dateTargets=[];
const iso=d=>[d.getFullYear(),String(d.getMonth()+1).padStart(2,'0'),String(d.getDate()).padStart(2,'0')].join('-');
function pairedDate(input){const pairs={launchDate:'endDate',endDate:'launchDate',dailyFrom:'dailyTo',dailyTo:'dailyFrom',start_date:'end_date',end_date:'start_date',logFrom:'logTo',logTo:'logFrom',bizDateFrom:'bizDateTo',bizDateTo:'bizDateFrom'},key=input.id||input.dataset.f||input.dataset.dashboard,other=pairs[key];if(!other)return [input];let root=input.closest('dialog,section,form')||document,match=input.dataset.f?root.querySelector(`[data-f="${other}"]`):input.dataset.dashboard?root.querySelector(`[data-dashboard="${other}"]`):root.querySelector('#'+other);return key.toLowerCase().includes('end')||key==='to'||key==='dailyTo'?[match,input].filter(Boolean):[input,match].filter(Boolean)}
function openDatePicker(input){dateTargets=pairedDate(input);dateForm.elements.from.value=dateTargets[0]?.value||'';dateForm.elements.to.value=(dateTargets[1]||dateTargets[0])?.value||dateTargets[0]?.value||'';datePicker.showModal()}
function enhanceDates(root=document){if(window.__ekkoNativeDates)return;const nodes=[];if(root.matches?.('input[type="date"]:not(.native-date)'))nodes.push(root);nodes.push(...$$('input[type="date"]:not(.native-date)',root));nodes.forEach(input=>{if(input.dataset.datePicker)return;input.dataset.datePicker='1';input.readOnly=true;input.addEventListener('pointerdown',e=>{e.preventDefault();openDatePicker(input)})})}enhanceDates();new MutationObserver(m=>m.forEach(x=>x.addedNodes.forEach(n=>n.nodeType===1&&enhanceDates(n)))).observe(document.body,{childList:true,subtree:true});
$('.date-presets',datePicker).onclick=e=>{let p=e.target.dataset.range;if(!p)return;let now=new Date(),a=new Date(now),b=new Date(now);if(p==='week')a.setDate(a.getDate()-6);if(p==='month30')a.setDate(a.getDate()-29);if(p==='month'){a=new Date(now.getFullYear(),now.getMonth(),1);b=new Date(now.getFullYear(),now.getMonth()+1,0)}dateForm.elements.from.value=p==='all'?'':iso(a);dateForm.elements.to.value=p==='all'?'':iso(b);$$('[data-range]',datePicker).forEach(x=>x.classList.toggle('active',x===e.target))};$('[data-date-cancel]',datePicker).onclick=()=>datePicker.close();dateForm.onsubmit=e=>{e.preventDefault();if(dateTargets[0]){dateTargets[0].value=dateForm.elements.from.value;dateTargets[0].dispatchEvent(new Event('change',{bubbles:true}))}if(dateTargets[1]){dateTargets[1].value=dateForm.elements.to.value;dateTargets[1].dispatchEvent(new Event('change',{bubbles:true}))}datePicker.close()};
/* Keep the familiar browser calendar behaviour.  The former paired range dialog
   intercepted every date field and made independent forms behave unexpectedly. */
window.__ekkoNativeDates=true;
$$('input[data-date-picker]').forEach(input=>{const clone=input.cloneNode(true);clone.readOnly=false;clone.removeAttribute('data-date-picker');input.replaceWith(clone)});

/* The original creative cards use the legacy entry id.  Reuse the same
   evaluation dialog contract as every new module instead of maintaining a
   second, visually different review component. */
window.EkkoOpenComments=async function(id){
  commentView.mode='new';commentView.page=1;
  let rows=await api(`/api/comments?entry=${encodeURIComponent(id)}`),d=document.createElement('dialog');
  d.className='business-comments-dialog creative-comments-dialog';
  const draw=()=>{d.innerHTML=commentShell('写下具体、可执行的团队评价。',rows);d.querySelector('[data-close]').onclick=()=>d.close()};
  draw();document.body.append(d);d.showModal();
  const live=async()=>{if(!d.open||document.activeElement?.closest('.comment-compose'))return;rows=await api(`/api/comments?entry=${encodeURIComponent(id)}`);draw()};
  document.addEventListener('ekko:comments',live);d.addEventListener('close',()=>{document.removeEventListener('ekko:comments',live);d.remove()},{once:true});
  d.onclick=async e=>{const target=e.target instanceof Element?e.target:null,sort=target?.closest('[data-sort]'),prev=target?.closest('[data-comment-prev]'),next=target?.closest('[data-comment-next]'),action=target?.closest('[data-like],[data-reply],[data-del]');if(sort){commentView.mode=sort.dataset.sort;commentView.page=1;return draw()}if(prev){commentView.page--;return draw()}if(next){commentView.page++;return draw()}if(!action)return;const {like,reply,del}=action.dataset;if(like){let all=await api('/api/comments/all'),c=all.find(x=>x.id===+like);await api('/api/comments/like',{id:+like,liked:!c?.liked});rows=await api(`/api/comments?entry=${encodeURIComponent(id)}`);return draw()}if(reply){let content=await textPrompt('回复评价','写下回复内容');if(content){await api(`/api/v1/comments/${reply}/replies`,{method:'POST',body:JSON.stringify({content})});rows=await api(`/api/comments?entry=${encodeURIComponent(id)}`);draw()}return}if(del)return ask('请确认','是否删除这条评价？',async()=>{await api('/api/comments/delete',{method:'POST',body:JSON.stringify({id:+del})});rows=await api(`/api/comments?entry=${encodeURIComponent(id)}`);draw()})};
  d.addEventListener('change',e=>{if(!e.target.matches('[data-comment-sort]'))return;commentView.mode=e.target.value;commentView.page=1;draw()});
  d.addEventListener('submit',async e=>{let form=e.target.closest('[data-comment-form]');if(!form)return;e.preventDefault();let value=form.querySelector('textarea').value.trim();if(!value)return;await api('/api/comments',{method:'POST',body:JSON.stringify({entryId:id,content:value})});rows=await api(`/api/comments?entry=${encodeURIComponent(id)}`);commentView.page=1;draw();document.dispatchEvent(new Event('ekko:comments'));toast('评价已发布')});
};

